const r = await tools["run_shell_command"]({command:"bun - <<'TS'
import ts from 'typescript';
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
const root = 'packages/agents/src/core';
const files: string[] = [];
function walk(dir: string) { for (const ent of readdirSync(dir, { withFileTypes: true })) { const p = join(dir, ent.name); if (ent.isDirectory()) walk(p); else if (/\.tsx?$/.test(ent.name) && !/\.d\.ts$/.test(ent.name)) files.push(p); } }
walk(root);
const found: {file:string; name:string; start:number; end:number; lines:number}[] = [];
for (const file of files) { const text = readFileSync(file, 'utf8'); const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
 function visit(node: ts.Node) {
  if (ts.isFunctionLike(node) && node.body) {
   let name = (node as ts.NamedDeclaration).name?.getText(sf);
   if (!name && ts.isVariableDeclaration(node.parent)) name = node.parent.name.getText(sf);
   if (!name && ts.isPropertyDeclaration(node.parent)) name = node.parent.name.getText(sf);
   if (!name && ts.isPropertyAssignment(node.parent)) name = node.parent.name.getText(sf);
   if (!name && ts.isMethodDeclaration(node)) name = node.name.getText(sf);
   const start = sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
   const end = sf.getLineAndCharacterOfPosition(node.end).line + 1;
   found.push({file:relative('.',file),name:name ?? '<anonymous>',start,end,lines:end-start+1});
  }
  ts.forEachChild(node, visit);
 }
 visit(sf);
}
found.sort((a,b)=>b.lines-a.lines || a.file.localeCompare(b.file) || a.start-b.start);
console.log(JSON.stringify(found.slice(0,10), null, 2));
